     "name": "string",
     "email": "user@example.com"
    },
    "receiver": {
     "name": "string",
     "email": "user@example.com"
    }
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

steps.code:
# Fetch all pages and store them
all_transactions = []
for page_index in range(3):
    page = apis.venmo.show_transactions(access_token=access_token, min_created_at='2023-05-01', max_created_at='2023-05-18', page_limit=20, page_index=page_index)
    if page:
        all_transactions.extend(page)
    else:
        break

print(f"Total transactions: {len(all_transactions)}")

# Compute sent and received sums
sent_total = 0.0
received_total = 0.0
for txn in all_transactions:
    if txn['sender']['email'] == 'jo-harr@gmail.com':
        sent_total += txn['amount']
    elif txn['receiver']['email'] == 'jo-harr@gmail.com':
        received_total += txn['amount']
    else:
        print(f"Unexpected transaction: {txn}")

print(f"Sent total: {sent_total}")
print(f"Received total: {received_total}")
print(f"Combined total: {sent_total + received_total}")

