steps.code:
# Fetch all phone contacts with relationship "friend" and all venmo friends to compare
phone_friend_emails = []
page_index = 0
page_limit = 20
while True:
    contacts = apis.phone.search_contacts(access_token=phone_token, relationship='friend', page_index=page_index, page_limit=page_limit)
    if not contacts:
        break
    for c in contacts:
        if c.get('email'):
            phone_friend_emails.append(c['email'])
    if len(contacts) < page_limit:
        break
    page_index += 1

venmo_friend_emails = []
page_index = 0
while True:
    friends = apis.venmo.search_friends(access_token=venmo_token, page_index=page_index, page_limit=page_limit)
    if not friends:
        break
    for f in friends:
        if f.get('email'):
            venmo_friend_emails.append(f['email'])
    if len(friends) < page_limit:
        break
    page_index += 1

print("Phone friend emails:", phone_friend_emails)
print("Venmo friend emails:", venmo_friend_emails)

