# Define the set of archived song IDs
archived_song_ids = {29, 43, 74, 127, 128, 131, 162, 172, 207, 257, 261, 280, 308, 311}

# Iterate through all playlists except the archived playlist (id=654)
for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    if playlist_id == 654:
        continue
    # Check each song in this playlist
    for song_id in playlist.get('song_ids', []):
        if song_id in archived_song_ids:
            result = apis.spotify.remove_song_from_playlist(playlist_id=playlist_id, song_id=song_id, access_token=spotify_token)
            print(f"Removed song {song_id} from playlist {playlist_id}: {result}")

# Verify all original playlists no longer contain any archived songs
all_playlists = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=spotify_token, page_index=page_index, page_limit=20)
    playlists = page if isinstance(page, list) else page.get('playlists', page.get('data', []))
    if not playlists:
        break
    all_playlists.extend(playlists)
    if len(playlists) < 20:
        break
    page_index += 1

archived_song_ids = {29, 43, 74, 127, 128, 131, 162, 172, 207, 257, 261, 280, 308, 311}
remaining_in_originals = []
for playlist in all_playlists:
    if playlist['playlist_id'] == 654:
        continue
    for song_id in playlist.get('song_ids', []):
        if song_id in archived_song_ids:
            remaining_in_originals.append((playlist['playlist_id'], song_id))

print("Remaining archived songs in original playlists:", remaining_in_originals)
print("All archived songs removed from originals:", len(remaining_in_originals) == 0)

# Remove matched songs from each original playlist (443-448)
matched_song_ids = {29, 43, 74, 127, 128, 131, 162, 172, 207, 257, 261, 280, 308, 311}
original_playlist_ids = [443, 444, 445, 446, 447, 448]

for pid in original_playlist_ids:
    playlist = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    songs = playlist['songs']
    for song in songs:
        if song['id'] in matched_song_ids:
            result = apis.spotify.remove_song_from_playlist(playlist_id=pid, song_id=song['id'], access_token=spotify_token)
            print(f"Removed song {song['id']} from playlist {pid}: {result}")

# Verify all matched songs have been removed from original playlists
matched_song_ids = {29, 43, 74, 127, 128, 131, 162, 172, 207, 257, 261, 280, 308, 311}
original_playlist_ids = [443, 444, 445, 446, 447, 448]

all_removed = True
for pid in original_playlist_ids:
    playlist = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    remaining_matched = [song['id'] for song in playlist['songs'] if song['id'] in matched_song_ids]
    if remaining_matched:
        all_removed = False
        print(f"Playlist {pid} still has matched songs: {remaining_matched}")
    else:
        print(f"Playlist {pid}: all matched songs removed")

print("All matched songs removed from original playlists:", all_removed)

