# Parse the archive list into (title, artist) tuples
archive_songs = []
for line in file_content['content'].splitlines():
    line = line.strip()
    if line.startswith('- '):
        song_str = line[2:]
        # Format: "Title by Artist"
        if ' by ' in song_str:
            title, artist = song_str.rsplit(' by ', 1)
            archive_songs.append((title.strip(), artist.strip()))
print(f"Parsed {len(archive_songs)} archive songs:")
for t, a in archive_songs:
    print(f"  {t} - {a}")

