# Correct verification: extract song IDs from 'songs' list in each playlist
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
all_playlists = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=login_result["access_token"], page_index=page_index, page_limit=20)
    if isinstance(page, dict):
        playlists_page = page.get("playlists", [])
    else:
        playlists_page = page
    all_playlists.extend(playlists_page)
    if len(playlists_page) < 20:
        break
    page_index += 1

issues = []
for pl in all_playlists:
    pl_id = pl["playlist_id"]
    pl_details = apis.spotify.show_playlist(playlist_id=pl_id, access_token=login_result["access_token"])
    song_ids = {song["id"] for song in pl_details.get("songs", [])}
    if pl_id == 654:
        missing = archived_song_ids - song_ids
        if missing:
            issues.append(f"Old Songs missing: {missing}")
    else:
        overlap = archived_song_ids & song_ids
        if overlap:
            issues.append(f"Playlist {pl_id} still has archived songs: {overlap}")

if issues:
    print("ISSUES:", issues)
else:
    print("All archived songs are only in 'Old Songs' playlist.")

