# Let's search for each old song and find the matching song IDs.
# We'll search by title and then filter by exact title and artist match.
old_song_ids = {}
for title, artists in old_songs:
    # Search with the title
    results = apis.spotify.search_songs(access_token=spotify_login['access_token'], query=title, page_limit=20)
    # Find exact match: title matches and all artists match
    found = None
    for song in results:
        if song['title'].lower() == title.lower():
            song_artist_names = [a['name'].lower() for a in song['artists']]
            expected_artists = [a.lower() for a in artists]
            # Check if all expected artists are in song's artists (order may differ)
            if all(any(exp == actual for actual in song_artist_names) for exp in expected_artists) and len(song_artist_names) == len(expected_artists):
                found = song['song_id']
                break
    if found is not None:
        old_song_ids[title] = found
        print(f"Found: {title} -> song_id {found}")
    else:
        print(f"NOT FOUND: {title}")

print("All old song IDs:", old_song_ids)

