# Let's search for each old song to get its song_id.
sp_token = spotify_login['access_token']
old_song_ids = []
for song in old_songs:
    query = song['title'] + ' ' + song['artist']
    results = apis.spotify.search_songs(query=query, access_token=sp_token)
    if results:
        # Pick the first result that matches title and artist
        found = False
        for r in results:
            if r['title'].lower() == song['title'].lower():
                # Check artist match
                artist_names = [a['name'] for a in r['artists']]
                # The artist string may have multiple names separated by comma
                expected_artists = [a.strip() for a in song['artist'].split(',')]
                if all(any(exp.lower() == an.lower() for an in artist_names) for exp in expected_artists):
                    old_songs_to.append({'song_id': r['song_id'], 'title': song['title'], 'artist': song['artist']})
                    found = True
                    break
        if not found:
            print(f"Could not find exact match for {song['title']} by {song['artist']}")
    else:
        print(f"No results for {song['title']} by {song['artist']}")

print("Found song IDs:")
for s in old_songs_to:
    print(s)

