steps.code:
# Parse the note content to extract songs and their release status
content = note['content']
lines = content.strip().split('\n')
songs = []
for line in lines:
    if line.startswith('- '):
        line = line[2:]
        # Split by " BY " to get title and artist part
        if ' BY ' in line:
            title_part, artist_part = line.split(' BY ', 1)
            # Check if RELEASED_AT is present
            if ' RELEASED_AT ' in artist_part:
                artist, released = artist_part.split(' RELEASED_AT ', 1)
                songs.append({'title': title_part.strip(), 'artists': artist.strip(), 'released': released.strip()})
            else:
                songs.append({'title': title_part.strip(), 'artists': artist_part.strip(), 'released': None})
        else:
            songs.append({'title': line.strip(), 'artists': '', 'released': None})

# Print songs missing release info
for s in songs:
    if s['released'] is None or s['released'] == 'TODO':
        print(s)

